package com.primehr.learningdevelopment.delivery.domain;
import com.primehr.learningdevelopment.domain.LdInterventionVersion;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.UUID;
@Entity@Table(name="ld_offering",uniqueConstraints={@UniqueConstraint(name="uk_ld_offering_series_version",columnNames={"agency_id","series_id","offering_version"}),@UniqueConstraint(name="uk_ld_offering_code_version",columnNames={"agency_id","normalized_code","offering_version"})})
public class LdOffering extends RspAuditedEntity{
 public enum Status{DRAFT,SUBMITTED,APPROVED,PUBLISHED,CANCELLED}
 @Column(name="series_id",nullable=false,length=36)private String seriesId;@Column(name="offering_version",nullable=false)private int offeringVersion;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="program_id",nullable=false,length=36)private String programId;@Column(name="program_version",nullable=false)private int programVersion;@Column(name="program_fingerprint",nullable=false,length=64)private String programFingerprint;@Column(nullable=false,length=80)private String code;@Column(name="normalized_code",nullable=false,length=80)private String normalizedCode;@Column(nullable=false,length=200)private String title;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private LdInterventionVersion.Modality modality;@Column(name="venue_or_platform",nullable=false,length=1000)private String venueOrPlatform;@Column(nullable=false)private int capacity;@Column(name="provider_id",length=36)private String providerId;@Column(name="provider_name",length=250)private String providerName;@Column(name="provider_fingerprint",length=64)private String providerFingerprint;@Column(name="evaluation_framework_version_id",nullable=false,length=36)private String evaluationFrameworkVersionId;@Column(name="evaluation_fingerprint",nullable=false,length=64)private String evaluationFingerprint;@Column(name="approved_budget",nullable=false,precision=19,scale=2)private BigDecimal approvedBudget;@Column(name="funding_source",nullable=false,length=500)private String fundingSource;@Column(name="currency_code",nullable=false,length=3)private String currencyCode;@Column(name="registration_open")private Instant registrationOpen;@Column(name="registration_close")private Instant registrationClose;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="content_revision",nullable=false)private int contentRevision;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="approved_by",length=100)private String approvedBy;@Column(name="approved_at")private Instant approvedAt;@Column(name="published_by",length=100)private String publishedBy;@Column(name="published_at")private Instant publishedAt;
 protected LdOffering(){}public LdOffering(String agency,String programId,int programVersion,String programFingerprint,String code,String title,LdInterventionVersion.Modality modality,String venue,int capacity,String providerId,String providerName,String providerFingerprint,String evaluationId,String evaluationFingerprint,BigDecimal budget,String funding,String currency,Instant registrationOpen,Instant registrationClose){super(agency);seriesId=UUID.randomUUID().toString();offeringVersion=1;this.programId=requiredText(programId,"programId");if(programVersion<1)throw new IllegalArgumentException("programVersion is required");this.programVersion=programVersion;this.programFingerprint=requiredText(programFingerprint,"programFingerprint");this.providerId=optionalText(providerId);this.providerName=optionalText(providerName);this.providerFingerprint=optionalText(providerFingerprint);if(this.providerId!=null&&(this.providerName==null||this.providerFingerprint==null))throw new IllegalArgumentException("Provider snapshot is incomplete");evaluationFrameworkVersionId=requiredText(evaluationId,"evaluationFrameworkVersionId");this.evaluationFingerprint=requiredText(evaluationFingerprint,"evaluationFingerprint");status=Status.DRAFT;contentRevision=1;apply(code,title,modality,venue,capacity,budget,funding,currency,registrationOpen,registrationClose);}
 public void update(String code,String title,LdInterventionVersion.Modality modality,String venue,int capacity,BigDecimal budget,String funding,String currency,Instant open,Instant close){editable();apply(code,title,modality,venue,capacity,budget,funding,currency,open,close);contentRevision++;}public void touch(){editable();contentRevision++;}public void submit(String actor,Instant at){editable();status=Status.SUBMITTED;submittedBy=requiredText(actor,"actor");submittedAt=at;}public void approve(String actor,Instant at){if(status!=Status.SUBMITTED)throw new IllegalStateException("Only a SUBMITTED offering may be approved");status=Status.APPROVED;approvedBy=requiredText(actor,"actor");approvedAt=at;}public void publish(String actor,Instant at){if(status!=Status.APPROVED)throw new IllegalStateException("Only an APPROVED offering may be published");status=Status.PUBLISHED;publishedBy=requiredText(actor,"actor");publishedAt=at;}public void cancel(){if(status==Status.CANCELLED)throw new IllegalStateException("L&D offering is already cancelled");status=Status.CANCELLED;}
 public LdOffering successor(){if(status!=Status.APPROVED&&status!=Status.PUBLISHED)throw new IllegalStateException("Only an APPROVED or PUBLISHED offering may be revised");LdOffering n=new LdOffering(getAgencyId(),programId,programVersion,programFingerprint,code,title,modality,venueOrPlatform,capacity,providerId,providerName,providerFingerprint,evaluationFrameworkVersionId,evaluationFingerprint,approvedBudget,fundingSource,currencyCode,registrationOpen,registrationClose);n.seriesId=seriesId;n.offeringVersion=offeringVersion+1;n.supersedesId=getId();return n;}
 private void apply(String c,String t,LdInterventionVersion.Modality m,String v,int cap,BigDecimal budget,String funding,String currency,Instant open,Instant close){code=requiredText(c,"code");normalizedCode=code.toUpperCase(java.util.Locale.ROOT);title=requiredText(t,"title");modality=java.util.Objects.requireNonNull(m);venueOrPlatform=requiredText(v,"venueOrPlatform");if(cap<1)throw new IllegalArgumentException("capacity must be positive");capacity=cap;if(budget==null||budget.signum()<0)throw new IllegalArgumentException("approvedBudget cannot be negative");approvedBudget=budget.setScale(2,RoundingMode.HALF_UP);fundingSource=requiredText(funding,"fundingSource");currencyCode=requiredText(currency,"currencyCode").toUpperCase(java.util.Locale.ROOT);if(currencyCode.length()!=3)throw new IllegalArgumentException("currencyCode must have three letters");if(open!=null&&close!=null&&close.isBefore(open))throw new IllegalArgumentException("registrationClose cannot precede registrationOpen");registrationOpen=open;registrationClose=close;}private void editable(){if(status!=Status.DRAFT)throw new IllegalStateException("Only a DRAFT offering may be changed");}
 public String getSeriesId(){return seriesId;}public int getOfferingVersion(){return offeringVersion;}public String getSupersedesId(){return supersedesId;}public String getProgramId(){return programId;}public int getProgramVersion(){return programVersion;}public String getProgramFingerprint(){return programFingerprint;}public String getCode(){return code;}public String getNormalizedCode(){return normalizedCode;}public String getTitle(){return title;}public LdInterventionVersion.Modality getModality(){return modality;}public String getVenueOrPlatform(){return venueOrPlatform;}public int getCapacity(){return capacity;}public String getProviderId(){return providerId;}public String getProviderName(){return providerName;}public String getProviderFingerprint(){return providerFingerprint;}public String getEvaluationFrameworkVersionId(){return evaluationFrameworkVersionId;}public String getEvaluationFingerprint(){return evaluationFingerprint;}public BigDecimal getApprovedBudget(){return approvedBudget;}public String getFundingSource(){return fundingSource;}public String getCurrencyCode(){return currencyCode;}public Instant getRegistrationOpen(){return registrationOpen;}public Instant getRegistrationClose(){return registrationClose;}public Status getStatus(){return status;}public int getContentRevision(){return contentRevision;}public String getSubmittedBy(){return submittedBy;}public Instant getSubmittedAt(){return submittedAt;}public String getApprovedBy(){return approvedBy;}public Instant getApprovedAt(){return approvedAt;}public String getPublishedBy(){return publishedBy;}public Instant getPublishedAt(){return publishedAt;}
}
